/// <reference lib="webworker" />
import { artifact, loadBinding } from 'virtual:openmates-rust-core-package';
import { validProductionBootstrap } from './productionBootstrap';
import { installBrowserCoreWorker } from '@openmates/ui/src/services/rustCore/workerRuntime';
import type { BrowserCoreBinding, WorkerEndpoint } from '@openmates/ui/src/services/rustCore/workerRuntime';

// Separate production asset entry; existing CI proof entry stays unchanged.
// Importing this bundle performs no admission, account read or credential IO.
const scope = self as DedicatedWorkerGlobalScope;
let started = false;
scope.addEventListener('message', async function bootstrap(event: MessageEvent<unknown>) {
  if (started) return;
  started = true; scope.removeEventListener('message',bootstrap);
  const configuration = event.data;
  if (!scope.isSecureContext || event.ports.length !== 0
    || !validProductionBootstrap(configuration,scope.location.origin,artifact)) { scope.close(); return; }
  try {
    const generated = await loadBinding() as BrowserCoreBinding;
    if (typeof generated.PreparedBrowserProfile?.from_existing_key !== 'function') throw Error('unavailable');
    installBrowserCoreWorker(scope as unknown as WorkerEndpoint,generated,
      {apiUrl:configuration.apiUrl,appOrigin:configuration.appOrigin,sessionId:configuration.sessionId,
        admission:'existing_key',expectedPrincipal:configuration.expectedPrincipal},scope.navigator.locks);
    scope.postMessage({version:1,ready:true});
  } catch {
    scope.postMessage({version:1,ready:false}); scope.close();
  }
});

import { openNativeRustChatIOFactory } from '@openmates/ui/src/services/rustCore/browserAdapters';
import workerUrl from './production.worker.ts?worker&url';
import { artifact, assets } from 'virtual:openmates-rust-core-package';
import { BrowserCoreWorkerHost } from '@openmates/ui/src/services/rustCore/workerHost';
import { validProductionBootstrap } from './productionBootstrap';
import type { ProductionBootstrap } from './productionBootstrap';

export const productionCoreAssets = Object.freeze({artifact,workerUrl,packageAssets:assets});

/** Explicit inactive composition point. No import-time Worker/auth/storage IO.
 * Caller must bind the complete profile lifecycle BEFORE capture/admission and
 * dispose this owned handle on teardown. This loader cannot grant authority or
 * close the outstanding cross-tab admission/production-route proof gates.
 */
export async function createProductionCoreWorker(input: {
  apiUrl: string; sessionId: string; expectedPrincipal: string; signal: AbortSignal;
}): Promise<{ host: BrowserCoreWorkerHost; close(): void }> {
  if (typeof window === 'undefined' || !window.isSecureContext || input.signal.aborted) throw Error('unavailable');
  const bootstrap: ProductionBootstrap = {version:1,operation:'bootstrap_existing_key',artifact:artifact ?? '',
    apiUrl:input.apiUrl,appOrigin:window.location.origin,sessionId:input.sessionId,expectedPrincipal:input.expectedPrincipal};
  if (!validProductionBootstrap(bootstrap,window.location.origin,artifact)) throw Error('rust_core_assets_disabled');
  const resolvedWorker = new URL(workerUrl,window.location.href);
  if (resolvedWorker.origin !== window.location.origin || resolvedWorker.username || resolvedWorker.password
    || resolvedWorker.search || resolvedWorker.hash || !resolvedWorker.pathname.includes('/_app/immutable/')) throw Error('invalid_asset_origin');
  const worker = new Worker(resolvedWorker,{type:'module',name:'openmates-rust-core'});
  let host: BrowserCoreWorkerHost | null = null;
  let closed = false;
  let rejectReady: (error: Error) => void = () => undefined;
  const close = () => {
    if (closed) return; closed = true;
    input.signal.removeEventListener('abort',close); window.removeEventListener('pagehide',close);
    rejectReady(Error('session_expired'));
    if (host) host.close(); else worker.terminate();
  };
  input.signal.addEventListener('abort',close,{once:true}); window.addEventListener('pagehide',close,{once:true});
  try {
    const nativeReadyEvent = await new Promise<MessageEvent<unknown>>((resolve,reject) => {
      const finish = (error?: Error, nativeEvent?: MessageEvent<unknown>) => {
        clearTimeout(timer); worker.removeEventListener('message',receive); worker.removeEventListener('messageerror',fail);worker.removeEventListener('error',fail);
        rejectReady = () => undefined; if (error) reject(error); else resolve(nativeEvent!);
      };
      rejectReady = error => finish(error);
      const fail = () => finish(Error('unavailable'));
      const receive = (event: MessageEvent<unknown>) => {
        const data = event.data;
        if (typeof data === 'object' && data !== null && Object.keys(data).length === 2
          && 'version' in data && data.version === 1 && 'ready' in data && data.ready === true) { finish(undefined,event); } else fail();
      };
      const timer = setTimeout(fail,30_000);
      worker.addEventListener('message',receive);worker.addEventListener('messageerror',fail);worker.addEventListener('error',fail);
      if (closed || input.signal.aborted) finish(Error('cancelled'));
      else { try { worker.postMessage(bootstrap); } catch { fail(); } }
    });
    if (closed || input.signal.aborted) throw Error('session_expired');
    const issuer = nativeReadyEvent?.isTrusted === true && nativeReadyEvent.target === worker
      ? openNativeRustChatIOFactory(worker, indexedDB, nativeReadyEvent) : undefined;
    host = new BrowserCoreWorkerHost(worker,undefined,input.expectedPrincipal,issuer);
    return {host,close};
  } catch { close(); throw Error('unavailable'); }
}

/** Explicit production saved-read composition; no caller/global activation is
 * installed. The existing platform source owns capture and exact revalidation.
 * This API neither mutates legacy persistence nor changes the deployed login.
 */
export async function createProductionSavedChatSession(input: import('@openmates/ui/src/services/rustCore/productionSavedChatSession').ProductionSavedChatSessionInput & {
  apiUrl: string; sessionId: string;
}): Promise<import('@openmates/ui/src/services/rustCore/productionSavedChatSession').ProductionSavedChatSession> {
  const { admitProductionSavedChatSession } = await import('@openmates/ui/src/services/rustCore/productionSavedChatSession');
  const { browserProfileLifecycle } = await import('@openmates/ui/src/services/rustCore/platformLifecycle');
  if (typeof window === 'undefined' || input.signal.aborted) throw Error('unavailable');
  return admitProductionSavedChatSession({ ...input, page: window, lifecycle: browserProfileLifecycle,
    createChannel: name => new BroadcastChannel(name),
    createWorker: signal => createProductionCoreWorker({apiUrl:input.apiUrl,sessionId:input.sessionId,
      expectedPrincipal:input.expectedPrincipal,signal}) });
}

/** Actual deployed auth/profile/key sources, explicit per-page opt-in only.
 * Callers select the chat/view generation; owner/Team/workspace and session ID
 * come from existing stores/storage. The supplied browser IO grants no authority.
 */
export async function createProductionSavedChatSessionFromBrowser(input: {
  signal: AbortSignal;
  currentSelection(): Omit<import('@openmates/ui/src/services/rustCore/selectedSavedChat').SavedChatSelection,'ownerId'|'teamId'|'workspaceEpoch'>;
}): Promise<import('@openmates/ui/src/services/rustCore/productionSavedChatSession').ProductionSavedChatSession> {
  if (typeof window === 'undefined' || input.signal.aborted) throw Error('unavailable');
  const [{ createBrowserSavedChatPlatform }, { getApiUrl }] = await Promise.all([
    import('@openmates/ui/src/services/rustCore/productionSavedChatPlatform'), import('@openmates/ui/src/config/api')
  ]);
  const platform = await createBrowserSavedChatPlatform(input.signal);
  try {
    const session = await createProductionSavedChatSession({ apiUrl:getApiUrl(),sessionId:platform.sessionId,
      expectedPrincipal:platform.expectedPrincipal,signal:input.signal,sources:platform.sources,
      currentSelection:()=>platform.selection(input.currentSelection()) });
    return { status:session.status,publish:publish=>session.publish(publish),publishPage:(selector,publish)=>session.publishPage(selector,publish),publishCheckpointSummary:(id,publish)=>session.publishCheckpointSummary(id,publish),startSend:text=>session.startSend(text),createSelectedChatObserver:io=>session.createSelectedChatObserver(io),withChatIORouting:(factory,gate,operation)=>session.withChatIORouting(factory,gate,operation),retireLegacyChatContext:(factory,options)=>session.retireLegacyChatContext(factory,options),createDraftEditorSession:()=>session.createDraftEditorSession(),async closeAndDrain(){try{await session.closeAndDrain();}finally{platform.close();}},close(){try{session.close();}finally{platform.close();}} };
  } catch(error) { platform.close(); throw error; }
}

/** Optional library ports only; normal application login remains unchanged. */
export {completeFreshOrdinaryRetention} from '@openmates/ui/src/services/rustCore/ordinaryLoginRetention';
export {captureBrowserOrdinaryRetentionContext} from '@openmates/ui/src/services/rustCore/ordinaryLoginRetentionBrowser';

/** Thin browser primitives. Rust chooses auth, ownership and persistence policy. */
export const AUTH_REFRESH_LOCK = "openmates:auth-session-refresh";

declare const refreshLeaseBrand: unique symbol;
export interface AuthRefreshLease { readonly [refreshLeaseBrand]: true }
declare const effectLeaseBrand: unique symbol;
export interface AuthRefreshEffectLease { readonly [effectLeaseBrand]: true }

type LeaseState = { active: boolean; signal: AbortSignal; current: () => void;
  controller: AbortController; pending: Set<Promise<unknown>> };
type LockState = LeaseState & { locks: LockManager };
type EffectState = LeaseState & { issuer: object; operationId: string };
