            .unwrap();
            let result = crate::platform::time::timeout(
                Duration::from_secs(3),
                client.list(Workspace::Chats),
            )
            .await
            .unwrap()
            .unwrap();
            assert!(result.is_empty());
            server.await.unwrap();
        }
